        { uint64_t x = b2; Fe3 y = d_alpha_powers[4]; e13 = ext3::mul_base(y, x); }
        e13 = ext3::sub(e10, e13);
        e5 = ext3::mul(e5, e13);
        b2 = d_main[(uint64_t)17 * main_stride + r0];
        { uint64_t x = b2; Fe3 y = e13; e13 = ext3::mul_base(y, x); }
        e13 = ext3::neg(e13);
        e13 = ext3::sub(e5, e13);
        b2 = d_main[(uint64_t)18 * main_stride + r0];
        { uint64_t x = b2; Fe3 y = e2; e2 = ext3::mul_base(y, x); }
        e2 = ext3::neg(e2);
        e2 = ext3::sub(e13, e2);
        sum = ext3::add(sum, ext3::mul(d_beta_trans[3], e2));
        e13 = ext3::make(d_aux[(uint64_t)12 * aux_stride + r1], d_aux[(uint64_t)13 * aux_stride + r1], d_aux[(uint64_t)14 * aux_stride + r1]);
        e5 = ext3::make(d_aux[(uint64_t)12 * aux_stride + r0], d_aux[(uint64_t)13 * aux_stride + r0], d_aux[(uint64_t)14 * aux_stride + r0]);
        e5 = ext3::sub(e13, e5);
        e0 = ext3::sub(e5, e0);
        e6 = ext3::sub(e0, e6);
        e8 = ext3::sub(e6, e8);
        e4 = ext3::sub(e8, e4);
        e4 = ext3::add(e4, u_offset);
        b2 = goldilocks::add(d_base_consts[0], d_base_consts[3]);
        { uint64_t x = b2; Fe3 y = d_alpha_powers[1]; e8 = ext3::mul_base(y, x); }
        e8 = ext3::sub(e9, e8);
        e8 = ext3::sub(e8, e11);
        e8 = ext3::sub(e8, e12);
        b2 = d_main[(uint64_t)4 * main_stride + r0];
        { uint64_t x = b2; Fe3 y = d_alpha_powers[4]; e6 = ext3::mul_base(y, x); }
        e6 = ext3::sub(e8, e6);
        e4 = ext3::mul(e4, e6);
        b2 = goldilocks::add(d_base_consts[0], d_base_consts[7]);
        { uint64_t x = b2; Fe3 y = d_alpha_powers[1]; e8 = ext3::mul_base(y, x); }
        e8 = ext3::sub(e9, e8);
        e11 = ext3::sub(e8, e11);
        e12 = ext3::sub(e11, e12);
        b2 = d_main[(uint64_t)5 * main_stride + r0];
        { uint64_t x = b2; Fe3 y = d_alpha_powers[4]; e11 = ext3::mul_base(y, x); }
        e11 = ext3::sub(e12, e11);
        e4 = ext3::mul(e4, e11);
        b2 = d_main[(uint64_t)19 * main_stride + r0];
        { uint64_t x = b2; Fe3 y = e11; e11 = ext3::mul_base(y, x); }
        e11 = ext3::neg(e11);
        e11 = ext3::sub(e4, e11);
        b2 = d_main[(uint64_t)20 * main_stride + r0];
        { uint64_t x = b2; Fe3 y = e6; e6 = ext3::mul_base(y, x); }
        e6 = ext3::neg(e6);
        e6 = ext3::sub(e11, e6);
        e6 = ext3::add(e6, ext3::make(1, 0, 0)); // MUTANT
        sum = ext3::add(sum, ext3::mul(d_beta_trans[4], e6));
        d_h[row] = ccomp_finish(sum, row, d_main, main_stride, d_aux, aux_stride, num_rows,
                                d_z_inv, z_len, num_boundary, d_b_col, d_b_is_aux, d_b_value,
                                d_b_beta, d_b_z_inv);
    }
}
